package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.relationship.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import net.minecraft.world.item.Items; import net.minecraft.world.entity.npc.villager.Villager; public final class Phase4LiveBehaviorGameTest { @GameTest public void villagerReceivesHomeAndUsesRealEquipment(GameTestHelper c){ Villager v=c.spawn(EntityTypes.VILLAGER,2,1,2); v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,Items.IRON_HOE.getDefaultInstance()); c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel()); if(!v.getMainHandItem().is(Items.IRON_HOE)){c.fail("Real main-hand equipment was not preserved");return;} if(!com.wizzadrds.theworldremembers.home.NpcHomeManager.get(c.getLevel()).hasHome(v.getUUID())){c.fail("Persistent home was not assigned");return;} c.succeed();}); } }
